parameters.jsCode:
const response = $json;

const text = response.candidates?.[0]?.content?.parts?.[0]?.text;

if (!text) {
  throw new Error("Gemini returned no text.");
}

let ai;

try {
  ai = JSON.parse(text);
} catch (e) {
  throw new Error(`Invalid Gemini JSON:\n${text}`);
}

const original = $("Route Merchant Category").item.json;

return {
  json: {
    ...original,

    display_name:
      ai.display_name ||
      original.display_name ||
      original.merchant,

    normalized_merchant:
      original.normalized_merchant,

    category:
      ai.category ||
      original.category ||
      "Other",

    confidence:
      Number(ai.confidence ?? 50),

    category_source: "ai"
  }
};

const txn = $json;

// Get original email metadata only as a fallback.
// Do NOT use Merge Statement + PDF anymore.
const source = $('Extract Password for Bank').first().json;

return {
  json: {
    ...txn,

    // -----------------------------------------
    // Preserve transaction metadata
    // -----------------------------------------

    message_id:
      txn.message_id ??
      source.message_id ??
      null,

    subject:
      txn.subject ??
      source.subject ??
      null,

    sender_email:
      txn.sender_email ??
      source.sender_email ??
      null,

    timestamp:
      txn.timestamp ??
      source.timestamp ??
      null,

    business_personal:
      txn.business_personal ??
      source.business_personal ??
      null,

    // -----------------------------------------
    // Parser-owned fields
    // NEVER overwrite these with old metadata
    // -----------------------------------------

    // Phase H: statement_id comes ONLY from the parent 'statements' row
    // created earlier in this execution -- never synthesized, never derived
    // from message_id.
    statement_id:
      $('Set Statement Context').item.json.statement_id,

    statement_period_start:
      txn.statement_period_start ?? null,

    statement_period_end:
      txn.statement_period_end ?? null,

    statement_date:
      txn.statement_date ?? null,

    due_date:
      txn.due_date ?? null,

    // Phase F: statement_month fallback chain. Current date is NEVER used.
    statement_month: (function () {
      if (txn.statement_month) return txn.statement_month;
      if (txn.statement_period_end) return String(txn.statement_period_end).slice(0, 7);
      if (txn.statement_period_start) return String(txn.statement_period_start).slice(0, 7);
      if (txn.statement_date) return String(txn.statement_date).slice(0, 7);
      return String(source.timestamp || new Date().toISOString()).slice(0, 7);
    })(),

    statement_month_source: (function () {
      if (txn.statement_month) return 'parser';
      if (txn.statement_period_end) return 'statement_period_end';
      if (txn.statement_period_start) return 'statement_period_start';
      if (txn.statement_date) return 'statement_date';
      return 'email_timestamp_fallback';
    })(),

    source_file:
      txn.source_file ?? null,

    bank_name:
      txn.bank_name ??
      source.bank_name ??
      null,

    parser_bank:
      txn.parser_bank ?? null,

    card_last4:
      txn.card_last4 ??
      source.card_last4 ??
      null,

    account_last4:
      txn.account_last4 ?? null,

    card_type:
      txn.card_type ?? 'Credit',

    account_type:
      txn.account_type ?? 'Credit Card',

    parser_version:
      txn.parser_version ?? 'v4',

    extraction_method:
      txn.extraction_method ?? 'native',

    parse_quality_status:
      txn.parse_quality_status ?? 'pass',

    fallback_reason:
      txn.fallback_reason ?? null
  }
};

const rawBankName = String($json.bank_name || '').trim();
if (!rawBankName) {
  throw new Error('Bank name could not be determined.');
}

// ============================================================
// BANK ALIAS MAP -- retained. This is bank-name normalization only
// (mapping the raw BANK_REGISTRY key to the canonical institution_name
// string used in Supabase), never per-card data. Phase 11.1 explicitly
// permits keeping this: "The workflow may retain bank aliases required
// to normalize/detect bank names."
// ============================================================
const BANK_ALIAS_MAP = {
  'HDFC': 'HDFC Bank', 'HDFC Bank': 'HDFC Bank',

  'ICICI': 'ICICI Bank', 'ICICI Bank': 'ICICI Bank',

  'YES': 'YES Bank', 'YES_Bank': 'YES Bank', 'YES Bank': 'YES Bank',

  'Axis': 'Axis Bank', 'Axis Bank': 'Axis Bank',

  'Kotak': 'Kotak Mahindra Bank', 'Kotak Mahindra': 'Kotak Mahindra Bank',
  'Kotak Mahindra Bank': 'Kotak Mahindra Bank',

  'IDFC': 'IDFC First Bank', 'IDFC First': 'IDFC First Bank',
  'IDFC_First': 'IDFC First Bank', 'IDFC First Bank': 'IDFC First Bank',

  'IndusInd': 'IndusInd Bank', 'IndusInd Bank': 'IndusInd Bank',

  'BOB': 'Bank of Baroda', 'Bank of Baroda': 'Bank of Baroda',
  'Bank_of_Baroda': 'Bank of Baroda',

  'RBL': 'RBL Bank', 'RBL Bank': 'RBL Bank',

  'SBI': 'State Bank of India', 'SBI_Card': 'State Bank of India', 'SBI Card': 'State Bank of India',
  'State Bank of India': 'State Bank of India',

  'AU': 'AU Bank', 'AU_Small_Finance': 'AU Bank',
  'AU Small Finance': 'AU Bank', 'AU Bank': 'AU Bank'
};

const canonicalBankName = BANK_ALIAS_MAP[rawBankName];

if (!canonicalBankName) {
  throw new Error(
    `UNSUPPORTED_BANK: "${rawBankName}" is not a recognized/configured bank. ` +
    `Supported: ${[...new Set(Object.values(BANK_ALIAS_MAP))].sort().join(', ')}`
  );
}

// ============================================================
// Phase 11.1: NO CARD_CONFIG. Card-level identity (last4, product,
// password) is no longer known to this node at all -- it is resolved
// entirely from live Supabase data by "Supabase: Get Account
// Credential" + "Validate Account Credential", immediately downstream.
// This node's only remaining job is to extract IDENTITY SIGNALS from
// the email evidence for those nodes to match against.
// ============================================================

// ============================================================
// PRE-PARSE CARD-IDENTITY SIGNALS
// Unchanged from Phase 11: the PDF is still encrypted at this point --
// the only information available is email metadata already on this
// item (subject, sender, email_body -- which already carries forwarded
// content wholesale, per "Extract Email Metadata") plus the attachment
// filename.
// ============================================================
const subject = String($json.subject || '');
const senderEmail = String($json.sender_email || '');
const filename = String(($binary && $binary.attachment_0 && $binary.attachment_0.fileName) || '');
const emailBody = String($json.email_body || '');
const haystack = [subject, senderEmail, filename, emailBody].join(' ');

function extractLast4(text) {
  const patterns = [
    /\bending\s*(?:with\s*)?[x*]{0,6}\s*(\d{4})\b/i,
    /\bcard\s*(?:no\.?|number)?\s*[x*]{2,}\s*(\d{4})\b/i,
    /[x*]{4,}\s*(\d{4})(?!\d)/i,
    /\blast\s*4\s*(?:digits?)?\s*[:\-]?\s*(\d{4})\b/i,
    /\bcard\s*[x*.]{0,6}\s*(\d{4})\b/i
  ];
  for (const re of patterns) {
    const m = text.match(re);
    if (m) return m[1];
  }
  return null;
}

const extractedLast4 = extractLast4(haystack);

// ------------------------------------------------------------
// Product-name normalization for matching only (unchanged function,
// now applied to the haystack itself rather than to a hardcoded
// CARD_CONFIG product list -- "Validate Account Credential" runs the
// same normalization on each Supabase candidate's card_product and
// checks it as a substring of this normalized haystack).
// ------------------------------------------------------------
function normalizeProductToken(value) {
  return String(value || '').toLowerCase().replace(/[^a-z0-9]/g, '');
}

const normalizedHaystack = normalizeProductToken(haystack);
const normalizedSubjectHaystack = normalizeProductToken(subject + ' ' + filename);

const ACCOUNT_TYPE = 'Credit Card';
const CARD_TYPE = 'Credit';

// ============================================================
// RETURN -- identity SIGNALS only. card_last4/business_personal/
// account_id/password are intentionally absent here now -- they are
// added by "Validate Account Credential" once the Supabase account
// row is actually resolved, and that node's output is what
// "Prepare Parser Request" consumes (same output contract/field names
// as Phase 11 -- see that node's code).
// ============================================================
return {
  json: {
    bank_name: canonicalBankName,
    parser_bank_name: rawBankName,
    extracted_last4: extractedLast4,
    normalized_haystack: normalizedHaystack,
    normalized_subject_haystack: normalizedSubjectHaystack,
    account_type: ACCOUNT_TYPE,
    card_type: CARD_TYPE,
    message_id: $json.message_id ?? null,
    subject: $json.subject ?? null,
    sender_email: $json.sender_email ?? null,
    timestamp: $json.timestamp ?? null
  },
  binary: $binary
};

// Runs on the MAIN output of "CC Parser API" (fullResponse + neverError means
// both HTTP 200 and HTTP 4xx/5xx land here as { statusCode, headers, body }).
// This node ONLY classifies the HTTP layer. Parse-quality evaluation (native vs
// fallback) happens next, in "Evaluate Parse Quality".
const res = $json;
const statusCode = res.statusCode;
const body = res.body || {};

if (statusCode === 200) {
  // Pass the full new-contract envelope through untouched.
  return {
    json: {
      parse_status: body.parse_status,
      extraction_method: body.extraction_method,
      fallback_available: body.fallback_available,
      fallback_reason: body.fallback_reason,
      parse_quality: body.parse_quality || {},
      bank: body.bank,
      data: body.data,
      raw_text: body.raw_text
      // routing_decision intentionally left unset here -- "Evaluate Parse Quality" sets it.
    }
  };
}

// --- HTTP-level error classification ---
// Exact error body shape wasn't specified beyond the status codes in the API
// contract (422 password_required, 401 invalid_password, 422 unsupported_bank).
// Reads common fields defensively; verify against a real error response and
// adjust the string matching below if field names differ.
const detail = String(body.detail || body.error || body.message || '').toLowerCase();

let errorCategory = 'unexpected_api_error';
if (statusCode === 401) {
  errorCategory = 'invalid_password';
} else if (statusCode === 422 && detail.includes('password')) {
  errorCategory = 'password_required';
} else if (statusCode === 422 && (detail.includes('bank') || detail.includes('unsupported'))) {
  errorCategory = 'unsupported_bank';
} else if (statusCode === 422 || detail.includes('parse') || detail.includes('parsing')) {
  errorCategory = 'pdf_parsing_failure';
}

return {
  json: {
    routing_decision: 'error',
    error_category: errorCategory,
    error_status_code: statusCode ?? null,
    error_message: body.detail || body.error || body.message || 'CC Parser API returned an error response.'
  }
};

// Only fires for genuine connection-level failures (DNS failure, connection
// refused, timeout) via onError:"continueErrorOutput" -- NOT HTTP status codes,
// which are handled on the main output via fullResponse + neverError instead.
const err = $json;
const message =
  (err.error && err.error.message) ||
  err.message ||
  'Could not reach CC Parser API (connection failure).';

return {
  json: {
    routing_decision: 'error',
    error_category: 'http_connection_failure',
    error_status_code: null,
    error_message: message
  }
};

// Single place that decides native vs fallback vs error, based on the
// documented contract:
//   Native:   parse_status == "success" AND parse_quality.status == "pass"
//   Fallback: parse_status == "fallback_required" OR parse_quality.status in
//             ("review","fail")  -- AND fallback_available AND raw_text present
//   Error:    anything else (including fallback claimed but raw_text missing)
//
// If "Classify Parser Response" / "Classify Connection Failure" already set
// routing_decision:'error' (an HTTP-level or connection-level failure), that
// decision is authoritative and is NOT re-evaluated here.
const j = $json;

if (j.routing_decision === 'error') {
  return { json: j };
}

const pq = j.parse_quality || {};
let decision = 'error';

if (j.parse_status === 'success' && pq.status === 'pass') {
  decision = 'native';
} else if (
  j.parse_status === 'fallback_required' ||
  pq.status === 'review' ||
  pq.status === 'fail'
) {
  decision = (j.fallback_available && j.raw_text) ? 'fallback' : 'error';
}

const out = { ...j, routing_decision: decision };

if (decision === 'error' && !out.error_category) {
  out.error_category = j.fallback_available
    ? 'pdf_parsing_failure'        // fallback claimed available but raw_text missing
    : 'pdf_parsing_failure';       // parse_quality failed and no fallback offered
  out.error_message = out.error_message
    || `parse_quality.status="${pq.status}", fallback_available=${j.fallback_available}, raw_text_present=${Boolean(j.raw_text)}`;
}

return { json: out };

parameters.jsonBody:
={
