}

parameters.jsCode:
// Never throws -- a bad/missing response is recorded as a soft failure and
// flows through "Validate AI Output" -> "AI Validation Gate" -> "Flag For Review"
// like any other validation failure, instead of killing the execution here.
const text = $json.candidates?.[0]?.content?.parts?.[0]?.text;

let parsed = null;
let parseError = null;

if (!text) {
  parseError = 'gemini_no_text_returned';
} else {
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    parseError = 'gemini_invalid_json';
  }
}

return {
  json: {
    gemini_output: parsed,
    gemini_parse_error: parseError
  }
};

// AI OUTPUT VALIDATION -- the hard gate between Gemini and the rest of the
// pipeline. Nothing from Gemini is trusted until it passes every check below.
//
// This is also the ONE place in the whole workflow that computes a reconciliation
// delta with an explicit tolerance (native trusts the API's own
// parse_quality.reconciliation_status directly and never recomputes this).
const CENTRAL_RECONCILIATION_TOLERANCE = 1; // currency units -- tune against real data

const j = $json;
const reasons = [];

if (j.gemini_parse_error) {
  return {
    json: {
      ai_validation_status: 'review',
      ai_validation_reasons: [j.gemini_parse_error],
      reconciliation_status: 'unknown',
      transactions: [],
      statement_total_amount_due: null,
      bank: null
    }
  };
}

const output = j.gemini_output || {};
const txns = Array.isArray(output.transactions) ? output.transactions : [];

if (txns.length === 0) reasons.push('zero_transactions');

const dateRe = /^\d{4}-\d{2}-\d{2}$/;
const seenRefs = new Set();
let duplicateRefs = false;
let missingRequired = false;

for (const t of txns) {
  if (!t.transaction_date || !dateRe.test(t.transaction_date)) { missingRequired = true; reasons.push('missing_dates'); }
  if (typeof t.amount !== 'number' || Number.isNaN(t.amount)) { missingRequired = true; reasons.push('missing_or_bad_amount'); }
  if (!t.merchant && !t.description) { missingRequired = true; reasons.push('empty_narration'); }
  if (t.debit_credit !== 'debit' && t.debit_credit !== 'credit') { missingRequired = true; reasons.push('missing_debit_credit'); }
  if (t.reference_number) {
    if (seenRefs.has(t.reference_number)) duplicateRefs = true;
    seenRefs.add(t.reference_number);
  }
}
if (duplicateRefs) reasons.push('duplicate_transaction_ids');

// Centralized reconciliation decision (AI-fallback path only).
let reconciliationStatus = 'reconciliation_unknown';
if (typeof output.statement_total_amount_due === 'number' && txns.length > 0) {
  const computedTotal = txns
    .filter(t => t.debit_credit === 'debit')
    .reduce((sum, t) => sum + (Number(t.amount) || 0), 0);
  const delta = Math.abs(computedTotal - output.statement_total_amount_due);
  reconciliationStatus = delta <= CENTRAL_RECONCILIATION_TOLERANCE ? 'pass' : 'fail';
  if (reconciliationStatus === 'fail') reasons.push('reconciliation_failed');
} else {
  reasons.push('reconciliation_unknown');
}

const hardFail = missingRequired || txns.length === 0;
const status = hardFail ? 'review' : (reconciliationStatus === 'fail' ? 'review' : 'pass');

return {
  json: {
    ai_validation_status: status,
    ai_validation_reasons: [...new Set(reasons)],
    reconciliation_status: reconciliationStatus,
    transactions: txns,
    statement_total_amount_due: output.statement_total_amount_due ?? null,
    bank: output.bank ?? null
  }
};

// Maps VALIDATED Gemini output into the exact same canonical per-transaction
// shape "Structured Transactions" (native path) produces: ONE n8n item PER
// transaction, so both paths converge into one schema downstream.
// (Previously this returned a single item holding a `transactions` array, which
// produced one malformed row instead of N rows.)
const messageId = $('Extract Password for Bank').first().json.message_id;
const src = $input.first().json;
const txns = src.transactions || [];
const evalItem = $('Evaluate Parse Quality').first().json;
const fallbackReason = evalItem.fallback_reason || null;
// Statement-level fields: Gemini output first, then whatever the native parser did extract.
const nat = evalItem.data || {};
const first = (...vals) => vals.find(v => v !== undefined && v !== null && v !== '') ?? null;

return txns.map(t => ({
  json: {
    transaction_date: t.transaction_date,
    message_id: messageId,
    merchant: t.merchant || t.description || '',
    description: t.description || t.merchant || '',
    amount: t.amount,
    currency: 'INR',
    debit_credit: t.debit_credit,
    // The native path stores 'debit' / 'credit' here; keep the AI path identical.
    transaction_type: t.transaction_type || t.debit_credit || (t.row_type === 'payment_refund' ? 'credit' : null),
    reference_number: t.reference_number || null,
    reward_points: t.reward_points ?? null,
    person: t.person ?? null,
    credit_reasons: t.credit_reasons ?? null,
    time: t.time ?? null,
    card_number: first(t.card_last4, nat.card_number),
    category_hint: null, // Gemini fallback never produces a native category_hint
    statement_month: first(src.statement_month, nat.statement_month),
    statement_period_start: first(src.statement_period_start, nat.statement_period_start),
    statement_period_end: first(src.statement_period_end, nat.statement_period_end),
    statement_date: first(src.statement_date, nat.statement_date),
    due_date: first(src.due_date, nat.due_date),
    statement_total_amount_due: first(src.statement_total_amount_due, nat.statement_total_amount_due),
    minimum_due: first(src.minimum_due, nat.minimum_due),
    closing_balance: first(src.closing_balance, nat.closing_balance),
    extraction_method: 'ai_fallback',
    parse_quality_status: src.ai_validation_status || 'pass',
    fallback_reason: fallbackReason
  }
}));

// ============================================================
// STRUCTURED TRANSACTIONS
// Native CC Parser path
// One input statement -> one n8n item per transaction
// ============================================================

const input = $input.first().json;

const passwordMeta =
  $('Extract Password for Bank').first().json;

const data = input.data || {};

const parseQualityStatus =
  input.parse_quality?.status || 'pass';

// ------------------------------------------------------------
// Source arrays
// ------------------------------------------------------------

const transactions = Array.isArray(data.transactions)
  ? data.transactions
  : [];

const paymentsRefunds = Array.isArray(data.payments_refunds)
  ? data.payments_refunds
  : [];

const messageId =
  passwordMeta.message_id || null;

// ------------------------------------------------------------
// Determine account/card type
//
// Priority:
// 1. Explicit metadata from Extract Password for Bank
// 2. Parser account_type
// 3. Presence of card number/card last4
//
// Credit-card statements:
//   card_last4   = populated
//   account_last4 = null
//
// Savings/current statements:
//   card_last4   = null
//   account_last4 = populated
// ------------------------------------------------------------

const explicitAccountType =
  passwordMeta.account_type ||
  data.account_type ||
  null;

const hasCardNumber =
  Boolean(data.card_number);

const hasCardLast4 =
  Boolean(passwordMeta.card_last4);

const normalizedAccountType =
  String(explicitAccountType || '').trim().toLowerCase();

const isSavings =
  normalizedAccountType === 'savings' ||
  normalizedAccountType === 'savings account';

const isCurrent =
  normalizedAccountType === 'current' ||
  normalizedAccountType === 'current account';

const isExplicitCreditCard =
  normalizedAccountType === 'credit card' ||
  normalizedAccountType === 'creditcard' ||
  normalizedAccountType === 'credit_card';

const isCardStatement =
  isExplicitCreditCard ||
  (!isSavings && !isCurrent && (hasCardNumber || hasCardLast4));

let accountType;

if (isCardStatement) {
  accountType = 'Credit Card';
} else if (isSavings) {
  accountType = 'Savings';
} else if (isCurrent) {
  accountType = 'Current';
} else {
  accountType = explicitAccountType || null;
}

// ------------------------------------------------------------
// Card / account last 4
// ------------------------------------------------------------

const parserCardLast4 =
  data.card_number
    ? String(data.card_number).slice(-4)
    : null;

const parserAccountLast4 =
  data.account_number
    ? String(data.account_number).slice(-4)
    : null;

const cardLast4 = isCardStatement
  ? (
      passwordMeta.card_last4 ||
      parserCardLast4 ||
      null
    )
  : null;

const accountLast4 = !isCardStatement
  ? (
      passwordMeta.account_last4 ||
      parserAccountLast4 ||
      null
    )
  : null;

// ------------------------------------------------------------
// Card type
// ------------------------------------------------------------

const cardType = isCardStatement
  ? (
      passwordMeta.card_type ||
      'Credit'
    )
  : null;

// ------------------------------------------------------------
// Statement-level metadata
// ------------------------------------------------------------

const statementMonth =
  data.statement_month || null;

const statementId =
  statementMonth && messageId
    ? `${messageId}_${statementMonth}`
    : null;

const statementMetadata = {
  statement_id: statementId,

  statement_month: statementMonth,

  statement_period_start:
    data.statement_period_start || null,

  statement_period_end:
    data.statement_period_end || null,

  due_date:
    data.due_date || null,

  statement_total_amount_due:
    data.statement_total_amount_due ?? null,

  minimum_due:
    data.minimum_due ?? null,

  closing_balance:
    data.closing_balance ?? null,

  source_file:
    data.file || null,

  bank_name:
    passwordMeta.bank_name ||
    data.bank ||
    null,

  parser_bank:
    data.bank || null,

  card_last4: cardLast4,

  account_last4: accountLast4,

  card_type: cardType,

  account_type: accountType,

  business_personal:
    passwordMeta.business_personal || null,

  sender_email:
    passwordMeta.sender_email || null,

  subject:
    passwordMeta.subject || null,

  timestamp:
    passwordMeta.timestamp || null,

  parser_version:
    input.parser_version || 'v4'
};

// ------------------------------------------------------------
// Helpers
// ------------------------------------------------------------

function mapDebitCredit(type) {
  const t = String(type || '').toLowerCase();

  if (
    t.includes('credit') ||
    t.includes('refund') ||
    t.includes('payment')
  ) {
    return 'credit';
  }

  if (
    t.includes('debit') ||
    t.includes('purchase')
  ) {
    return 'debit';
  }

  return null;
}

function buildTransaction(txn, fallbackType = null) {
  return {
    ...statementMetadata,

    // --------------------------------------------------------
    // Transaction fields
    // --------------------------------------------------------

    transaction_date:
      txn.date || null,

    merchant:
      txn.narration || '',

    description:
      txn.narration || '',

    amount:
      txn.amount ?? null,

    currency:
      txn.currency || 'INR',

    debit_credit:
      mapDebitCredit(txn.transaction_type) ||
      fallbackType ||
      null,

    transaction_type:
      txn.transaction_type ||
      fallbackType ||
      null,

    reference_number:
      txn.transaction_id || null,

    reward_points:
      txn.reward_points ?? null,

    person:
      txn.person ?? null,

    credit_reasons:
      txn.credit_reasons ?? null,

    time:
      txn.time ?? null,

    // For cards, keep card number.
    // For savings/current, use account number if parser provides it.
    card_number:
      isCardStatement
        ? (
            txn.card_number ||
            data.card_number ||
            null
          )
        : null,

    account_number:
      !isCardStatement
        ? (
            txn.account_number ||
            data.account_number ||
            null
          )
        : null,

    category_hint:
      txn.category_hint ??
      data.category_hint ??
      data.default_category_hint ??
      null,

    // --------------------------------------------------------
    // Statement-level fields (Phase F: statement_month fallback source)
    // --------------------------------------------------------
    statement_month:
      data.statement_month ?? null,
    statement_period_start:
      data.statement_period_start ?? null,
    statement_period_end:
      data.statement_period_end ?? null,
    statement_date:
      data.statement_date ?? null,
    due_date:
      data.due_date ?? null,
    statement_total_amount_due:
      data.statement_total_amount_due ?? null,
    minimum_due:
      data.minimum_due ?? null,
    closing_balance:
      data.closing_balance ?? null,

    // --------------------------------------------------------
    // Audit fields
    // --------------------------------------------------------

    extraction_method:
      'native',

    parse_quality_status:
      parseQualityStatus,

    fallback_reason:
      null
  };
}

// ------------------------------------------------------------
// Build debit transactions
// ------------------------------------------------------------

const normalizedTransactions =
  transactions.map(txn =>
    buildTransaction(txn)
  );

// ------------------------------------------------------------
// Build payments / refunds
// ------------------------------------------------------------

const normalizedPaymentsRefunds =
  paymentsRefunds.map(pr =>
    buildTransaction(pr, 'credit')
  );

// ------------------------------------------------------------
// Combine
// ------------------------------------------------------------

const allTransactions = [
  ...normalizedTransactions,
  ...normalizedPaymentsRefunds
];

// ------------------------------------------------------------
// IMPORTANT:
// Run Once for All Items -> return array of n8n items
// ------------------------------------------------------------

return allTransactions.map(transaction => ({
  json: transaction
}));

// Priority tier 2: merchant wasn't in memory, but the native parser already
// supplied a deterministic category_hint -- use it instead of calling Gemini.
// (Deliberately NOT written to merchant memory here -- a hint is a per-statement
// suggestion, not a confirmed merchant categorization. Easy to add later if wanted.)
const j = $json;
return {
  json: {
    ...j,
    display_name: j.display_name || j.merchant || 'Unknown Merchant',
    category: j.category_hint,
    confidence: j.category_hint_confidence ?? 70,
    category_source: 'parser_category_hint'
  }
};

// Shared failure handler for: a hard CC Parser error/connection failure, a
// failed AI-output validation, or a failed final-transaction validation.
// There is still no dedicated review/error queue in the Supabase schema, so
// this throws a descriptive error -- full context lands in the n8n Execution
// log, which is where failures already show up today. If a persistent review
// queue is wanted later, the smallest addition is one Supabase table plus an
// insert step here instead of throwing.
const j = $json;

let stage = 'unknown';
let reason = 'unclassified failure';
let detail = null;

if (j.validation_status === 'fail') {
  stage = 'final_validation';
  reason = (j.validation_missing_fields || []).join(', ') || 'required fields missing';
  detail = j.validation_missing_fields || null;
} else if (j.ai_validation_status === 'review') {
  stage = 'ai_validation';
  reason = (j.ai_validation_reasons || []).join(', ') || 'ai validation failed';
  detail = j.ai_validation_reasons || null;
} else if (j.routing_decision === 'error') {
  stage = 'parsing';
  reason = j.error_category || 'unexpected_api_error';
  detail = j.error_message || null;
}

const ctx = $('Extract Password for Bank').item.json;

const context = {
  stage,
  message_id: ctx.message_id || null,
  bank_name: ctx.bank_name || null,
  subject: ctx.subject || null,
  timestamp: ctx.timestamp || null,
  reason,
  detail
};

throw new Error(`Bank statement flagged for review [${context.stage}]: ${context.reason} -- ${JSON.stringify(context)}`);

// Pure construction -- validation now happens in "Validate Final Transaction"
// right after this node, not here. amount/confidence are never coerced from
// null to 0 -- a missing amount stays null so the validator catches it.
const j = $json;

return {
  json: {
    // Phase C: configuration-driven owner id. Fails loudly (not silently null)
    // if the env var is missing, so we never write financial data under an
    // undefined owner.
    user_id: (() => {
  const uid = "2f324f4d-1dc3-4ec5-8c23-93da480842c7";

  if (!uid) {
    throw new Error(
      "SUPABASE_OWNER_USER_ID is not configured -- refusing to write financial data."
    );
  }

  return uid;
})(),

    statement_id: j.statement_id || null,
    statement_month: j.statement_month || null,
    statement_period_start: j.statement_period_start || null,
    statement_period_end: j.statement_period_end || null,
    due_date: j.due_date || null,
    statement_total_amount_due: j.statement_total_amount_due || null,
    minimum_due: j.minimum_due || null,
    closing_balance: j.closing_balance || null,

    bank_name: j.bank_name || null,

    source_file: j.source_file || null,
    page_number: j.page_number || null,

    parser_version: "v3",
    extraction_method: j.extraction_method || null,

    card_last4: j.card_last4 || null,
    account_last4: j.account_last4 || null,
    card_type: j.card_type || null,
    account_type: j.account_type || null,

    transaction_date: j.transaction_date || null,

    amount: (j.amount === null || j.amount === undefined || j.amount === '') ? null : Number(j.amount),
    currency: j.currency || "INR",

    merchant: j.display_name || j.merchant || null,
    merchant_normalized: j.normalized_merchant || null,
    raw_description: j.description || null,

    payment_mode: j.payment_mode || j.debit_credit || null,
    transaction_type: j.transaction_type || null,
    reference_number: j.reference_number || null,

    category: j.category || null,
    category_source: j.category_source || null,
    confidence: (j.confidence === null || j.confidence === undefined || j.confidence === '') ? null : Number(j.confidence),

    status: "processed",
    note: null,

    metadata: {
      message_id: j.message_id || null,
      email_subject: j.subject || null,
      merchant_id: j.merchant_id || null,
      parser: j.extraction_method === 'ai_fallback' ? 'CC Parser (fallback) + Gemini' : 'CC Parser (native)',
      extraction_method: j.extraction_method || null,
      parse_quality_status: j.parse_quality_status || null,
      fallback_reason: j.fallback_reason || null,
      parser_version: "v3",
      business_personal: j.business_personal || null
    }
  }
};

// The final hard gate. No required financial field may be null, and a
// missing amount is NEVER treated as 0 -- it fails validation instead.
const j = $json;
const REQUIRED_FIELDS = ['user_id', 'bank_name', 'transaction_date', 'amount', 'currency', 'merchant', 'transaction_type', 'category', 'status'];

const missing = REQUIRED_FIELDS.filter(f => j[f] === null || j[f] === undefined || j[f] === '');

if (typeof j.amount !== 'number' || Number.isNaN(j.amount)) {
  if (!missing.includes('amount')) missing.push('amount');
}

return {
  json: {
    ...j,
    validation_status: missing.length === 0 ? 'pass' : 'fail',
    validation_missing_fields: missing
  }
};

const bankName = String($json.bank_name || '').trim();

// ============================================================
// CANONICAL BANK NAME -> CC PARSER BANK ID
//
// Values on the right are cc-parser-api's own canonical bank ids,
// confirmed directly against its source (app/bank_ids.py's
// BANK_ID_TO_UPSTREAM / SUPPORTED_BANKS, and app/parsing.py's
// normalize_bank -> normalize_bank_id, which is exactly what
// app/main.py's POST /parse validates the "bank" form field against).
// None of these are guessed -- every value below is one of that file's
// own SUPPORTED_BANKS entries.
//
// Phase 9.2 adds the 5 mappings that were missing: kotak, idfc,
// indusind, bob, rbl. Note IDFC's real parser id is "idfc", NOT
// "idfc_first" -- confirmed from the parser source, not assumed from
// the workflow's own "IDFC First Bank" naming.
//
// Existing HDFC/ICICI/Axis/SBI_Card/YES_Bank/AU_Small_Finance mappings
// are unchanged -- all 6 already matched the parser's own SUPPORTED_BANKS
// exactly (hdfc, icici, axis, sbi, yes_bank, zenith_au).
// ============================================================
const parserBankMap = {
  HDFC: 'hdfc',
  'HDFC Bank': 'hdfc',

  ICICI: 'icici',
  'ICICI Bank': 'icici',

  Axis: 'axis',
  'Axis Bank': 'axis',

  SBI_Card: 'sbi',
  'SBI Card': 'sbi',
  'State Bank of India': 'sbi',

  YES_Bank: 'yes_bank',
  'YES Bank': 'yes_bank',

  AU_Small_Finance: 'zenith_au',
  'AU Bank': 'zenith_au',

  // ---- Phase 9.2 additions -- confirmed against cc-parser-api's own
  // ---- app/bank_ids.py, not guessed.
  Kotak: 'kotak',
  'Kotak Mahindra': 'kotak',
  'Kotak Mahindra Bank': 'kotak',

  IDFC: 'idfc',
  'IDFC First': 'idfc',
  'IDFC_First': 'idfc',
  'IDFC First Bank': 'idfc',

  IndusInd: 'indusind',
  'IndusInd Bank': 'indusind',

  BOB: 'bob',
  'Bank of Baroda': 'bob',
  'Bank_of_Baroda': 'bob',

  RBL: 'rbl',
  'RBL Bank': 'rbl'
};

const parser_bank = parserBankMap[bankName];

if (!parser_bank) {
  throw new Error(
    `No CC Parser bank mapping for "${bankName}". ` +
    `Available: ${Object.keys(parserBankMap).join(', ')}`
  );
}

return {
  json: {
    ...$json,
    parser_bank
  },
  binary: $binary
};

// Clean, successful termination for a duplicate Gmail message.
// No error is thrown -- this is expected, normal behavior on re-delivery/retry.
const existing = $input.all()[0]?.json || {};
return [{
  json: {
    status: 'skipped_duplicate',
    reason: 'statement already processed for this Gmail message',
    existing_statement_id: existing.id || null,
    message_id: $('Extract Email Metadata').first().json.message_id
  }
}];

// Collapses the per-row category rows from Supabase into one context item
// reused by every categorization/validation node downstream.
const rows = $input.all().map(i => i.json);

const names = rows
  .map(r => r.name || r.category_name || r.label || r.category)
  .filter(Boolean);

const uniqueNames = [...new Set(names)];

if (uniqueNames.length === 0) {
  // Fail loud rather than silently falling back to a stale hardcoded list --
  // an empty canonical list would make every category look 'invalid'.
  throw new Error('Load Canonical Categories returned no usable category names. Check the categories table / field mapping before proceeding.');
}

return [{
  json: {
    canonical_categories: uniqueNames,
    canonical_categories_csv: uniqueNames.join(', '),
    canonical_default_category: uniqueNames.includes('Other') ? 'Other' : uniqueNames[0]
  }
}];

// Hard gate: any category not present in the canonical Supabase list is
// replaced with the default (never dropped, never allowed through unchanged).
const j = $json;
const canon = $('Normalize Canonical Categories').item.json;
const list = canon.canonical_categories || [];
const fallback = canon.canonical_default_category || 'Other';
const incoming = (j.category || '').trim();
const isValid = list.some(c => c.toLowerCase() === incoming.toLowerCase());
return {
  json: {
    ...j,
    category: isValid ? incoming : fallback,
    category_validation_status: isValid ? 'pass' : 'corrected_to_default',
    category_original_value: isValid ? null : incoming
  }
};

// Hard gate: any category not present in the canonical Supabase list is
// replaced with the default (never dropped, never allowed through unchanged).
const j = $json;
const canon = $('Normalize Canonical Categories').item.json;
const list = canon.canonical_categories || [];
const fallback = canon.canonical_default_category || 'Other';
const incoming = (j.category || '').trim();
const isValid = list.some(c => c.toLowerCase() === incoming.toLowerCase());
return {
  json: {
    ...j,
    category: isValid ? incoming : fallback,
    category_validation_status: isValid ? 'pass' : 'corrected_to_default',
    category_original_value: isValid ? null : incoming
  }
};

// Phase 3 fix (Issue 1): consumes the result of "Get Statement Transactions"
// -- an authoritative Supabase query for ALL statement_transactions rows
// belonging to this statement_id -- instead of $input.all() sourced
// directly from the current execution's insert stream. This is resume-safe:
// on a resumed execution this reflects every row actually stored under this
// statement_id, not just the rows this particular execution inserted.
const rows = $('Get Statement Transactions').all().map(i => i.json);

const debits = rows.filter(t => (t.transaction_type || t.debit_credit) === 'debit');
const credits = rows.filter(t => (t.transaction_type || t.debit_credit) === 'credit');

const sum = arr => arr.reduce((s, t) => s + (Number(t.amount) || 0), 0);

// Phase 3 fix (Issue 2): statement_period_start/statement_period_end/due_date
// are not columns on statement_transactions, so they can't come from the
// query above. They are parser-owned and identical for every transaction in
// this statement, so they're read from this execution's own "Build Final
// Transaction Row" output. .first() is used (not .item) because the new
// Supabase read node breaks the paired-item chain back to that node.
const meta = $('Build Final Transaction Row').first().json;

// Phase 4 fix: resolve statements.account_id against the accounts fetched
// by "Resolve Account: Get Accounts" (this node's immediate input). Shared,
// identical contract with Workflow C's "Resolve Account: Match": match on
// institution_name + (card_last4 if present, else account_last4). Never
// guesses -- 0 or >1 candidates leaves account_id null.
const accounts = $input.all().map(i => i.json);

function normAcct(s) { return (s == null ? '' : String(s)).trim().toLowerCase(); }

// Phase 7 fix: canonical bank-name map. Keys are the EXACT bank_name
// values "Extract Email Metadata"'s own BANK_REGISTRY produces (read
// directly from that node's code, not guessed) -- NOTE this registry is a
// separate, independently-written implementation from Workflow C's "Bank
// Detection" node, with different key casing AND different bank coverage
// (e.g. Workflow D has no Standard_Chartered/Citi/HSBC entries at all;
// Workflow C has no RBL/Bank_of_Baroda/SBI_Card). The two are NOT the same
// vocabulary internally -- this map's job is only to translate Workflow
// D's own keys to the canonical accounts.institution_name form, which
// Workflow C's Resolve Account: Match already targets. Verified against
// live accounts data for HDFC/ICICI/Axis/SBI_Card/American_Express; the
// rest are UNVERIFIED placeholders (no live account row yet to confirm).
const BANK_NAME_MAP = {
  HDFC: 'HDFC Bank',
  ICICI: 'ICICI Bank',
  Axis: 'Axis Bank',
  SBI_Card: 'State Bank of India',
  American_Express: 'American Express',
  AU_Small_Finance: 'AU Bank',                 // CONFIRMED by live test (Phase 8)
  YES_Bank: 'YES Bank',                        // UNVERIFIED
  Kotak: 'Kotak Mahindra Bank',                // UNVERIFIED
  IDFC_First: 'IDFC FIRST Bank',               // UNVERIFIED
  IndusInd: 'IndusInd Bank',                   // UNVERIFIED
  RBL: 'RBL Bank',                             // UNVERIFIED
  Bank_of_Baroda: 'Bank of Baroda',            // UNVERIFIED
};


// Phase 5 fix: compute account_match_status instead of finalizing
// account_id here -- "Account Needs Creation?" (IF) + "Create Account If
// Missing" (Supabase insert) + "Merge Account Resolution" now decide
// whether an unmatched, unambiguous identifier gets a brand-new accounts
// row. Never guesses: 0 matches -> no_match (may auto-create downstream),
// >1 matches -> ambiguous (never auto-created, never assigned).
const canonicalBankName = BANK_NAME_MAP[meta?.bank_name] || meta?.bank_name || null;
const accountType = meta?.account_type || null;

// Phase 8 fix: a credit card has a CARD last-4; a savings/current/OD
// account has an ACCOUNT last-4. These must never be compared against the
// wrong column, and never coalesced together -- the prior resolvedLast4()
// helper did exactly that, which is a latent correctness gap even though
// it wasn't the actual cause of the AU Bank incident (that was the
// BANK_NAME_MAP entry above, now corrected). account_type also decides
// WHICH accounts column to compare, applied as a strict filter, not just
// "preferably" -- this removes any chance of a same-institution
// savings/credit-card pair cross-matching on a coincidentally equal digit
// string.
let identifierField, sourceIdentifier;
if (accountType === 'Credit Card') {
  identifierField = 'card_last4';
  sourceIdentifier = meta?.card_last4 || null;
} else if (accountType) {
  // Any non-card account_type (Savings/Current/OD/...) -- the existing
  // account_type value from the accounts table decides the label, this
  // workflow never invents a new one.
  identifierField = 'account_last4';
  sourceIdentifier = meta?.account_last4 || null;
} else {
  identifierField = null;
  sourceIdentifier = null;
}

let account_match_status;
let candidates = [];

if (!sourceIdentifier) {
  // Covers: account_type unknown/missing, OR the correct identifier field
  // for this account_type (card_last4 for a card, account_last4
  // otherwise) is itself null. Never falls back to the other field.
  account_match_status = 'missing_identifier';
} else {
  candidates = accounts.filter(a =>
    normAcct(a.institution_name) === normAcct(canonicalBankName) &&
    normAcct(a[identifierField]) === normAcct(sourceIdentifier) &&
    normAcct(a.account_type) === normAcct(accountType)
  );
  if (candidates.length === 0) account_match_status = 'no_match';
  else if (candidates.length > 1) account_match_status = 'ambiguous';
  else account_match_status = 'existing_account';
}

let account_id = account_match_status === 'existing_account' ? candidates[0].id : null;
// The card was already uniquely identified (and its password verified) by
// "Validate Account Credential". Prefer that over re-deriving it from the PDF's
// card digits, which can be missing or masked (e.g. "XX26") and would otherwise
// leave the statement unlinked or trigger a duplicate auto-created account.
const validatedAccountId = $('Validate Account Credential').first().json.account_id || null;
if (validatedAccountId) {
  account_id = validatedAccountId;
  account_match_status = 'existing_account';
}

return [{
  json: {
    statement_id: $('Set Statement Context').first().json.statement_id,
    account_id,
    account_match_status,
    bank_name: canonicalBankName,
    canonical_bank_name: canonicalBankName,
    account_type: meta?.account_type || null,
    card_last4: meta?.card_last4 || null,
    account_last4: meta?.account_last4 || null,
    transaction_count: rows.length,
    total_debits: sum(debits),
    total_credits: sum(credits),
    statement_period_start: meta?.statement_period_start || null,
    statement_period_end: meta?.statement_period_end || null,
    due_date: meta?.due_date || null,
    statement_total_amount_due: meta?.statement_total_amount_due || null,
    minimum_due: meta?.minimum_due || null,
    closing_balance: meta?.closing_balance || null,
    parser_version: rows[0]?.parser_version || null,
    extraction_method: rows[0]?.extraction_method || null
  }
}];

// Single reference point for 'which statements.id applies to this execution'.
// Fed by 'Start Statement (get or create)' (new or resumed row). Downstream nodes read
// it by name via $('Set Statement Context').
const j = $input.first().json;
return [{
  json: {
    statement_id: j.id,
    source_message_id: j.source_message_id,
    statement_resumed: Boolean(j.resumed)
  }
}];

// Reconverges the "Account Needs Creation?" branches. Exactly one of the
// two upstream branches produced this item:
//   - TRUE branch (Create Account If Missing): this item IS the freshly
//     created accounts row (has .id, no .account_match_status).
//   - FALSE branch (direct passthrough): this item is Aggregate Statement
//     Totals' own output, already carrying account_id/account_match_status
//     (existing_account, ambiguous, or no_identifier).
// .first() is used for "Aggregate Statement Totals" because Create Account
// If Missing breaks the paired-item chain back to it, same reasoning as
// every other cross-node read added in this account-resolution work.
const totals = $('Aggregate Statement Totals').first().json;
const cur = $json;

let account_id, account_match_status;
if (cur.account_match_status !== undefined) {
  account_id = cur.account_id;
  account_match_status = cur.account_match_status;
} else {
  account_id = cur.id;
  account_match_status = 'account_created';
}

// Never mark a statement completed while its account is ambiguous.
const processing_status = account_match_status === 'ambiguous' ? 'needs_review' : 'completed';

const notes = `Workflow D -- bank=${totals.bank_name || 'unknown'} -- account_match=${account_match_status}` +
  (account_match_status === 'ambiguous'
    ? ' -- REVIEW REQUIRED: multiple matching accounts, none assigned'
    : '');

return [{
  json: {
    statement_id: totals.statement_id,
    transaction_count: totals.transaction_count,
    total_debits: totals.total_debits,
    total_credits: totals.total_credits,
    statement_period_start: totals.statement_period_start,
    statement_period_end: totals.statement_period_end,
    due_date: totals.due_date,
    statement_total_amount_due: totals.statement_total_amount_due,
    minimum_due: totals.minimum_due,
    closing_balance: totals.closing_balance,
    parser_version: totals.parser_version,
    extraction_method: totals.extraction_method,
    account_id,
    account_match_status,
    processing_status,
    notes
  }
}];

// ============================================================
// Phase 11.1: DYNAMIC card identity resolution. Supabase is the sole
// source of truth for which (bank, card_last4, card_product) rows
// exist -- this node consults no hardcoded per-card registry of any
// kind. Never guesses: a genuine conflict between last4 and product
// evidence, or a failure to uniquely identify a row at all, fails
// loudly with a distinct, named error -- the same "fail safe, never
// silently pick" discipline this workflow has always used. Passwords
// are never logged, never included in an error message, never
// returned from this node except as the "password" field the parser
// HTTP call consumes.
// ============================================================
const rows = $input.all().map(i => i.json);

const source = $('Extract Password for Bank').first().json;
const bankName = source.bank_name;
const extractedLast4 = source.extracted_last4 || null;
const normalizedHaystack = source.normalized_haystack || '';

if (rows.length === 0) {
  throw new Error(
    `ACCOUNT_NOT_FOUND: no accounts row exists for institution_name="${bankName}", ` +
    `account_type="Credit Card" at all. Add the account row in Supabase before this ` +
    `statement can be processed.`
  );
}

function normalizeProductToken(value) {
  return String(value || '').toLowerCase().replace(/[^a-z0-9]/g, '');
}

// ---- Tier 1: bank + card_last4 -- the strongest identifier ----
let last4Resolved = null;
if (extractedLast4) {
  const last4Matches = rows.filter(r => r.card_last4 === extractedLast4 || r.source_card_last4 === extractedLast4);
  if (last4Matches.length > 1) {
    throw new Error(
      `AMBIGUOUS_ACCOUNT: ${last4Matches.length} accounts rows share institution_name="${bankName}", ` +
      `card_last4="${extractedLast4}", account_type="Credit Card". Exactly one is required -- fix the ` +
      `duplicate account rows in Supabase.`
    );
  }
  if (last4Matches.length === 1) last4Resolved = last4Matches[0];
  // last4Matches.length === 0 is not itself a hard failure here -- a
  // mis-extracted last4 is plausible; product evidence below gets a
  // chance instead of failing on a possibly-wrong digit match.
}

// ---- Tier 2: bank + normalized product -- used standalone when
// last4 is unavailable/unmatched, and cross-checked against last4
// below when both independently resolve. ----
// Candidate product tokens ignore a trailing generic "card" word ("Uni Card" -> "uni").
// The email subject + attachment filename are checked first (precise); the full
// email body is only a fallback, because body text can contain short product words.
function productToken(r) {
  const t = normalizeProductToken(r.card_product);
  const stripped = t.endsWith('card') && t.length > 4 ? t.slice(0, -4) : t;
  return stripped || t;
}
const subjectHaystack = source.normalized_subject_haystack || '';
function uniqueProductMatch(haystack) {
  const m = rows.filter(r => r.card_product && haystack.includes(productToken(r)));
  return m.length === 1 ? m[0] : null;
}
// Body text is only consulted when last4 gave no answer: a last4 match is never second-guessed
// by incidental product words in forwarded email boilerplate.
const productResolved = uniqueProductMatch(subjectHaystack) || (last4Resolved ? null : uniqueProductMatch(normalizedHaystack));

// ---- Combine per the required priority: last4 is strongest; product
// is the fallback; if BOTH independently resolve, they must agree. ----
let resolved = null;

if (last4Resolved && productResolved) {
  if (last4Resolved.id !== productResolved.id) {
    throw new Error(
      `IDENTITY_CONFLICT: card_last4 evidence points to account ${last4Resolved.id} ` +
      `(card_last4="${last4Resolved.card_last4}"), but product-name evidence points to a ` +
      `different account ${productResolved.id} (card_product="${productResolved.card_product}"). ` +
      `Refusing to guess -- correct the email evidence or the Supabase account data.`
    );
  }
  resolved = last4Resolved;
} else if (last4Resolved) {
  resolved = last4Resolved;
} else if (productResolved) {
  resolved = productResolved;
}

if (!resolved) {
  throw new Error(
    `CARD_NOT_IDENTIFIED: bank "${bankName}" has ${rows.length} configured account(s) in Supabase, ` +
    `but neither card_last4 nor a product name could be uniquely matched from the email. Refusing to guess.`
  );
}

// ---- Existing Phase 11 validations, preserved ----
const isInactive = resolved.account_status != null
  ? String(resolved.account_status).toLowerCase() !== 'active'
  : resolved.is_active === false;

if (isInactive) {
  throw new Error(
    `ACCOUNT_INACTIVE: the matched account (institution_name="${bankName}", ` +
    `card_last4="${resolved.card_last4}") is not active (account_status="${resolved.account_status}", ` +
    `is_active=${resolved.is_active}). Reactivate the account before this statement can be processed.`
  );
}

if (!resolved.statement_password) {
  throw new Error(
    `CREDENTIAL_NOT_CONFIGURED: the matched account (institution_name="${bankName}", ` +
    `card_last4="${resolved.card_last4}") has no statement_password configured in Supabase. Set ` +
    `accounts.statement_password for this row before this statement can be processed.`
  );
}

// ============================================================
// RETURN -- same output contract "Prepare Parser Request" (and every
// downstream consumer of business_personal/account_id/card_last4)
// already expects, per Phase 11. card_last4 and business_personal are
// now authoritatively sourced from the resolved Supabase row rather
// than from a hardcoded registry.
// ============================================================
return {
  json: {
    bank_name: source.bank_name,
    parser_bank_name: source.parser_bank_name,
    card_last4: resolved.card_last4,
    account_last4: null,
    account_type: source.account_type,
    card_type: source.card_type,
    business_personal: resolved.account_category || null,
    message_id: source.message_id,
    subject: source.subject,
    sender_email: source.sender_email,
    timestamp: source.timestamp,
    account_id: resolved.id,
    password: resolved.statement_password
  },
  binary: $('Extract Password for Bank').first().binary
};
